// Language of the UI: English by default, German as an option (button at the top right, remembered in this browser).
// German is the source and the key: t(german) gives the English text unless German is chosen.
// Placeholders in braces, filled from the second argument ({ n: 3 }). Missing entries stay German;
// tests/test_i18n.py checks that every text has an entry with the same placeholders.
'use strict';

const stored = (() => { try { return localStorage.getItem('wb-lang'); } catch (_) { return null; } })();
export let LANG = stored === 'de' ? 'de' : 'en';
document.documentElement.lang = LANG === 'en' ? 'en' : 'de-CH';

export function setLang(l) {
  LANG = l === 'en' ? 'en' : 'de';
  try { localStorage.setItem('wb-lang', LANG); } catch (_) { /* storage unavailable */ }
  document.documentElement.lang = LANG === 'en' ? 'en' : 'de-CH';
}
export const locale = () => LANG === 'en' ? 'en-GB' : 'de-CH';

export function t(de, vars) {
  const s = LANG === 'en' ? (EN[de] ?? de) : de;
  return vars ? s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m)) : s;
}

